using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing.Editor {
public static partial class ComponentsCircuitVerification {
 static readonly List<string> checks=new List<string>();static void Check(bool ok,string text){checks.Add((ok?"PASS ":"FAIL ")+text);File.WriteAllLines("Verification/Components/rules.txt",checks);if(!ok)throw new Exception(text);}static void Reject(Action action,string text){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,text);}
 static string Id()=>Guid.NewGuid().ToString("N");static TrialSession Finish(TrialDefinition d){var s=new TrialSession(d);s.Tick(4,Vector3.zero,Vector3.zero);s.Tick(90,Vector3.zero,Vector3.zero);foreach(var g in d.checkpoints)s.Tick(.02f,g.Position-g.Forward,g.Position+g.Forward);return s;}
 static void Parts(RaceProgressStore s,string part){var c=WorkshopCatalog.ForBuild(s.ActiveModelId,s.ActiveWorkshop);foreach(var offer in c.MissingPath(s.ActiveWorkshop,c.Find(part)))s.PurchaseWorkshop(Id(),offer.id,c.Price(s.ActiveWorkshop,offer),out _);}
 static CircuitSession Result(CircuitContract c,TrialDefinition route,int beaten){var s=new CircuitSession(c,route);var zeros=new Vector3[7];s.Tick(4,Vector3.zero,Vector3.zero,zeros,zeros);foreach(var gate in route.checkpoints){var from=(Vector3[])zeros.Clone();var to=(Vector3[])zeros.Clone();for(int i=0;i<7-beaten;i++){from[i]=gate.Position-gate.Forward;to[i]=gate.Position+gate.Forward;}s.Tick(.02f,Vector3.zero,Vector3.zero,from,to);}foreach(var gate in route.checkpoints)s.Tick(.02f,gate.Position-gate.Forward,gate.Position+gate.Forward,zeros,zeros);return s;}
 public static void Run(){Directory.CreateDirectory("Verification/Components");checks.Clear();var route=JsonUtility.FromJson<TrialDefinition>(Resources.Load<TextAsset>("FirstDocksideTrial").text);string folder=Path.GetFullPath("Verification/Components/profiles/"+Id());Directory.CreateDirectory(folder);string old=Path.GetFullPath("Verification/Components/fixtures/released-v9.json"),oldBytes=File.ReadAllText(old);var before=JsonUtility.FromJson<RaceProgress>(oldBytes);var migrated=new RaceProgressStore(folder+"/migrated.json",route,componentsLegacyFile:old);Check(migrated.Profile.version==10&&migrated.Profile.availableCredits==before.availableCredits&&migrated.Profile.prototypeCarId==before.prototypeCarId&&JsonUtility.ToJson(migrated.Profile.spending)==JsonUtility.ToJson(before.spending),"Released v9 migrates to v10 preserving all historical money/receipts/car identity");Check(migrated.Profile.fleet.parts.Count==0&&File.ReadAllText(old)==oldBytes,"Migration invents no loose kits and leaves old v9 bytes unchanged");
 var store=new RaceProgressStore(folder+"/fresh.json",route);string unchanged=File.ReadAllText(store.PathName);Reject(()=>store.BeginCircuit(Id()),"Insufficient3000credit entry is rejected");Check(File.ReadAllText(store.PathName)==unchanged,"Rejected entry cannot alter money/history");for(int i=0;i<160;i++)store.Settle(Finish(route),out _);Parts(store,"induction_small_3");string car=store.Profile.fleet.selectedId,engine=FleetLedger.Find(store.Profile.fleet,car).engineId;var catalog=WorkshopCatalog.ForBuild(store.ActiveModelId,store.ActiveWorkshop);float boosted=catalog.Resolve(store.ActiveWorkshop).PeakKw();Reject(()=>store.ComponentRemovalFee(car,"cooling"),"Cooling removal blocked while high-boost calibration requires it");int fee=store.ComponentRemovalFee(car,"induction"),cash=store.Profile.availableCredits;string remove=Id();store.RemoveComponent(remove,car,"induction",fee);store.RemoveComponent(remove,car,"induction",fee);var unit=store.Profile.fleet.parts.Single();string kit=unit.id;Check(fee==250&&store.Profile.availableCredits==cash-250&&store.Profile.fleet.parts.Count==1&&unit.status=="stored"&&unit.stage==3,"Paid turbo removal and retry create one real Stage3 kit and charge250once");Check(store.ActiveWorkshop.induction=="none"&&store.ActiveWorkshop.coolingStage==2&&!catalog.Resolve(store.ActiveWorkshop).IsTurbo&&catalog.Resolve(store.ActiveWorkshop).PeakKw()<boosted,"Turbo removal clears real boost/torque while retaining paid passive cooler");int fit=store.ComponentFitFee(kit,car),fitCash=store.Profile.availableCredits;string fitId=Id();store.FitComponent(fitId,kit,car,fit);store.FitComponent(fitId,kit,car,fit);Check(store.Profile.availableCredits==fitCash-250&&store.ActiveWorkshop.inductionStage==3&&store.Profile.fleet.parts.Single().id==kit&&store.Profile.fleet.parts.Single().status=="installed","Owned Stage3 kit refits for labor only, without repaying preceding stages or duplicating identity");Check(Math.Abs(catalog.Resolve(store.ActiveWorkshop).PeakKw()-boosted)<.001f,"Refit restores exact authored boosted power");Reject(()=>store.RemoveComponent(fitId,car,"induction",250),"Conflicting component request cannot reuse committed ID");store.RemoveComponent(Id(),car,"induction",250);Check(store.Profile.fleet.parts.Count==1&&store.Profile.fleet.parts.Single().id==kit,"Repeated removal reuses same physical component unit");
 var fault=new RaceProgressStore(store.PathName,route,()=>{throw new IOException("Injected component failure");});string snapshot=File.ReadAllText(store.PathName);Reject(()=>fault.FitComponent(Id(),kit,car,250),"Injected component write failure is reported");Check(File.ReadAllText(store.PathName)==snapshot&&new RaceProgressStore(store.PathName,route).Profile.fleet.parts.Single().status=="stored","Atomic failure preserves money/engine/part state");store.FitComponent(Id(),kit,car,250);
 string request=Id();int entryCash=store.Profile.availableCredits;var contract=store.BeginCircuit(request);store.BeginCircuit(request);Check(store.Profile.availableCredits==entryCash-3000&&contract.rivals.Length==7&&CircuitLedger.Pending(store.Profile.fleet),"Circuit entry and retry charge3000once and freeze seven real rival builds");Check(contract.rivals.Any(r=>r.modelId=="car_bastion"&&r.build.induction=="roots")&&contract.rivals.Any(r=>r.modelId=="car_tempest"),"Circuit contains supercharged V8 muscle and original exotic sports rivals");Reject(()=>store.RemoveComponent(Id(),car,"induction",250),"Committed circuit blocks paid component changes");Reject(()=>store.PullEngine(Id(),car),"Committed circuit blocks engine removal");Reject(()=>store.BeginDuel(Id(),"rookie","cash"),"Committed circuit cannot overlap another race");var tie=Result(contract,route,3);Check(tie.Resolved&&tie.Result.beaten==3,"Ordered finish timing counts only rivals actually finished ahead of");store.SettleCircuit(tie);store.SettleCircuit(tie);Check(store.Profile.availableCredits==entryCash&&!store.Profile.fleet.HasPending,"Beating three pays3000once and exactly breaks even");
 int start=store.Profile.availableCredits;var win=Result(store.BeginCircuit(Id()),route,7);store.SettleCircuit(win);Check(store.Profile.availableCredits==start+4000,"Beating seven pays7000gross for4000net after entry");start=store.Profile.availableCredits;var last=Result(store.BeginCircuit(Id()),route,0);store.SettleCircuit(last);Check(store.Profile.availableCredits==start-3000,"Last place loses3000entry with no reward");start=store.Profile.availableCredits;store.BeginCircuit(Id());store.ForfeitDuel();Check(store.Profile.availableCredits==start-3000&&!store.Profile.fleet.HasPending,"Existing interruption/quit path forfeits circuit entry without losing car title");Check(FleetLedger.Find(store.Profile.fleet,car).owner=="player","Cash circuit never stakes car or fitted engine ownership");var loaded=new RaceProgressStore(store.PathName,route);Check(JsonUtility.ToJson(loaded.Profile.fleet)==JsonUtility.ToJson(store.Profile.fleet)&&loaded.Profile.availableCredits==store.Profile.availableCredits,"Components and circuit settlements replay exactly after reload");var future=JsonUtility.FromJson<RaceProgress>(File.ReadAllText(store.PathName));future.version=11;string futureFile=folder+"/future.json";File.WriteAllText(futureFile,JsonUtility.ToJson(future));File.WriteAllText(futureFile+".bak",File.ReadAllText(store.PathName));Reject(()=>new RaceProgressStore(futureFile,route),"Future schema11 is rejected without silent older-backup overwrite");Check(File.ReadAllText(old)==oldBytes,"All component/circuit operations preserve legacy source bytes");Extra(folder,route);}
}
